WITH sales_per_order AS (SELECT cs_order_number, cs_call_center_sk, cs_warehouse_sk, SUM(cs_net_profit) AS order_sales_profit FROM catalog_sales GROUP BY cs_order_number, cs_call_center_sk, cs_warehouse_sk), returns_per_order AS (SELECT cr_order_number, cr_call_center_sk, cr_warehouse_sk, SUM(cr_net_loss) AS order_return_loss FROM catalog_returns GROUP BY cr_order_number, cr_call_center_sk, cr_warehouse_sk), combined AS (SELECT s.cs_call_center_sk, s.cs_warehouse_sk, s.cs_order_number, s.order_sales_profit, COALESCE(r.order_return_loss, 0) AS order_return_loss, s.order_sales_profit - COALESCE(r.order_return_loss, 0) AS net_profit_after_returns FROM sales_per_order s LEFT JOIN returns_per_order r ON s.cs_order_number = r.cr_order_number AND s.cs_call_center_sk = r.cr_call_center_sk AND s.cs_warehouse_sk = r.cr_warehouse_sk), agg AS (SELECT cc.cc_call_center_id, cc.cc_name, cc.cc_state, cc.cc_division, w.w_warehouse_name, SUM(c.net_profit_after_returns) AS total_net_profit FROM combined c JOIN call_center cc ON c.cs_call_center_sk = cc.cc_call_center_sk JOIN warehouse w ON c.cs_warehouse_sk = w.w_warehouse_sk GROUP BY cc.cc_call_center_id, cc.cc_name, cc.cc_state, cc.cc_division, w.w_warehouse_name) SELECT agg.cc_call_center_id, agg.cc_name, agg.cc_state, agg.cc_division, agg.w_warehouse_name, agg.total_net_profit, CASE WHEN agg.total_net_profit > 1000000 THEN 'High' WHEN agg.total_net_profit BETWEEN 500000 AND 1000000 THEN 'Medium' ELSE 'Low' END AS profit_category, RANK() OVER (PARTITION BY agg.cc_division ORDER BY agg.total_net_profit DESC) AS division_profit_rank FROM agg ORDER BY division_profit_rank, agg.cc_call_center_id
